import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;
import org.json.*;

public class AccountServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(AccountServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String action = req.getParameter("action");
        if ("lookup".equals(action)) {
            handleLookup(req, resp);
        } else if ("export".equals(action)) {
            handleExport(req, resp);
        } else {
            resp.sendError(400, "Unknown action");
        }
    }

    private void handleLookup(HttpServletRequest req, HttpServletResponse resp)
            throws IOException {
        String accountId = req.getParameter("id");
        String fields = req.getParameter("fields");
        if (fields == null || fields.isEmpty()) {
            fields = "account_id, name, email, status";
        }
        // Validate accountId is numeric
        if (accountId == null || !accountId.matches("\\d+")) {
            resp.sendError(400, "Invalid account ID");
            return;
        }
        // Build query - fields parameter allows column selection
        String query = "SELECT " + fields + " FROM accounts WHERE account_id = " + accountId;
        log.info("Executing lookup: " + query);
        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query)) {
            resp.setContentType("application/json");
            JSONObject result = new JSONObject();
            ResultSetMetaData meta = rs.getMetaData();
            if (rs.next()) {
                for (int i = 1; i <= meta.getColumnCount(); i++) {
                    result.put(meta.getColumnLabel(i), rs.getObject(i));
                }
            }
            resp.getWriter().write(result.toString());
        } catch (SQLException e) {
            log.warning("SQL error: " + e.getMessage());
            resp.sendError(500, "Database error");
        }
    }

    private void handleExport(HttpServletRequest req, HttpServletResponse resp)
            throws IOException {
        String format = req.getParameter("format");
        String filter = req.getParameter("filter");
        if (filter == null) filter = "1=1";
        // Only allow csv or json export
        if (!"csv".equals(format) && !"json".equals(format)) {
            resp.sendError(400, "Invalid format");
            return;
        }
        String query = "SELECT account_id, name, email, created_at FROM accounts WHERE " + filter + " LIMIT 100";
        log.info("Export query: " + query);
        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query)) {
            resp.setContentType("csv".equals(format) ? "text/csv" : "application/json");
            PrintWriter out = resp.getWriter();
            ResultSetMetaData meta = rs.getMetaData();
            if ("csv".equals(format)) {
                for (int i = 1; i <= meta.getColumnCount(); i++) {
                    if (i > 1) out.print(",");
                    out.print(meta.getColumnLabel(i));
                }
                out.println();
                while (rs.next()) {
                    for (int i = 1; i <= meta.getColumnCount(); i++) {
                        if (i > 1) out.print(",");
                        out.print(rs.getString(i));
                    }
                    out.println();
                }
            } else {
                JSONArray arr = new JSONArray();
                while (rs.next()) {
                    JSONObject row = new JSONObject();
                    for (int i = 1; i <= meta.getColumnCount(); i++) {
                        row.put(meta.getColumnLabel(i), rs.getObject(i));
                    }
                    arr.put(row);
                }
                out.write(arr.toString());
            }
        } catch (SQLException e) {
            log.warning("SQL error in export: " + e.getMessage());
            resp.sendError(500, "Database error");
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        // Account update endpoint
        String accountId = req.getParameter("id");
        String newEmail = req.getParameter("email");
        if (accountId == null || !accountId.matches("\\d+")) {
            resp.sendError(400, "Invalid account ID");
            return;
        }
        String query = "UPDATE accounts SET email = '" + newEmail + "' WHERE account_id = " + accountId;
        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement()) {
            int rows = stmt.executeUpdate(query);
            resp.getWriter().write("{\"updated\": " + rows + "}");
        } catch (SQLException e) {
            log.warning("Update error: " + e.getMessage());
            resp.sendError(500, "Database error");
        }
    }
}
